1	import { Link, useNavigate } from 'react-router-dom';
2	import type { Post } from '../api/post';
3	
4	interface TopicTableProps {
5	  posts?: Post[];
6	}
7	
8	/**
9	 * CC98 经典主题帖列表表格组件 (绑定目标项目的 Post 实体数据)
10	 */
11	export default function TopicTable({ posts = [] }: TopicTableProps) {
12	  const navigate = useNavigate();
13	  const safePosts = posts || [];
14	
15	  const handleRowClick = (postId: number, e: React.MouseEvent) => {
16	    const target = e.target as HTMLElement;
17	    // Don't trigger row navigation if clicking on specific links (like author profile or category)
18	    if (
19	      target.closest('.cc98-author-link') ||
20	      target.closest('.cc98-last-author') ||
21	      target.closest('.cc98-topic-table-category')
22	    ) {
23	      return;
24	    }
25	    navigate(`/posts/${postId}`);
26	  };
27	
28	  if (safePosts.length === 0) {
29	    return (
30	      <div className="cc98-empty-table">
31	        <i className="fa fa-folder-open-o" style={{ fontSize: '2.5rem', display: 'block', marginBottom: '1rem', color: 'var(--text-muted)' }}></i>
32	        暂无帖子
33	      </div>
34	    );
35	  }
36	
37	  // 格式化时间显示 (e.g. 刚刚，几分钟前，或者正常日期)
38	  const formatTime = (timeStr: string) => {
39	    try {
40	      const now = new Date();
41	      const date = new Date(timeStr.replace(/-/g, '/')); // 兼容 Safari
42	      const diffMs = now.getTime() - date.getTime();
43	      
44	      const diffMins = Math.floor(diffMs / (1000 * 60));
45	      const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
46	      
47	      if (diffMins < 1) return '刚刚';
48	      if (diffMins < 60) return `${diffMins} 分钟前`;
49	      if (diffHours < 24) return `${diffHours} 小时前`;
50	      
51	      return timeStr.split('T')[0] || timeStr;
52	    } catch {
53	      return timeStr;
54	    }
55	  };
56	
57	  return (
58	    <table className="cc98-topic-list">
59	      <thead className="cc98-tl-header">
60	        <tr>
61	          <th className="cc98-tl-cell cc98-tl-status" style={{ width: '45px' }}></th>
62	          <th className="cc98-tl-cell cc98-tl-title">主题标题</th>
63	          <th className="cc98-tl-cell cc98-tl-author" style={{ width: '130px' }}>作者</th>
64	          <th className="cc98-tl-cell cc98-tl-stats" style={{ width: '120px' }}>回复/点击</th>
65	          <th className="cc98-tl-cell cc98-tl-last" style={{ width: '180px' }}>最后发表</th>
66	        </tr>
67	      </thead>
68	      <tbody>
69	        {safePosts.map((post) => {
70	          const isSticky = post.status === 'STICKY';
71	          const replyCount = post.commentCount ?? 0;
72	          const viewCount = post.viewCount;
73	
74	          return (
75	            <tr 
76	              key={post.id} 
77	              className={`cc98-tl-row ${isSticky ? 'sticky-row' : ''} card`}
78	              onClick={(e) => handleRowClick(post.id, e)}
79	              style={{ cursor: 'pointer' }}
80	            >
81	              {/* 1. Status Icon */}
82	              <td className="cc98-tl-cell cc98-tl-status">
83	                {isSticky ? (
84	                  <i className="fa fa-thumb-tack sticky" title="置顶主题"></i>
85	                ) : replyCount >= 10 ? (
86	                  <i className="fa fa-fire hot" title="热门讨论"></i>
87	                ) : (
88	                  <i className="fa fa-file-text-o normal" title="普通主题"></i>
89	                )}
90	              </td>
91	
92	              {/* 2. Title with Category Tag */}
93	              <td className="cc98-tl-cell cc98-tl-title-cell">
94	                <div className="cc98-title-container">
95	                  {post.categoryId && post.categoryName && (
96	                    <Link 
97	                      to={`/category/${post.categoryId}`} 
98	                      className="cc98-topic-table-category"
99	                    >
100	                      [{post.categoryName}]
101	                    </Link>
102	                  )}
103	
104	                  <Link 
105	                    to={`/posts/${post.id}`} 
106	                    className={`cc98-topic-link ${isSticky ? 'sticky-title' : ''}`}
107	                  >
108	                    {post.title}
109	                  </Link>
110	                  {replyCount >= 15 && (
111	                    <span className="cc98-hot-spark">HOT</span>
112	                  )}
113	                </div>
114	              </td>
115	
116	              {/* 3. Author info */}
117	              <td className="cc98-tl-cell cc98-tl-author">
118	                <Link to={`/profile/${post.authorUsername}`} className="cc98-author-link">
119	                  {post.authorUsername}
120	                </Link>
121	                <div className="cc98-author-time">
122	                  {post.createdAt.split('T')[0]}
123	                </div>
124	              </td>
125	
126	              {/* 4. Stats badges */}
127	              <td className="cc98-tl-cell cc98-tl-stats">
128	                <span className="cc98-stat-badge cc98-stat-replies" title="回复数">
129	                  {replyCount}
130	                </span>
131	                <span className="cc98-stat-divider">/</span>
132	                <span className="cc98-stat-badge cc98-stat-views" title="阅读量">
133	                  {viewCount}
134	                </span>
135	              </td>
136	
137	              {/* 5. Last reply info */}
138	              <td className="cc98-tl-cell cc98-tl-last">
139	                <div className="cc98-last-by">
140	                  <Link to={`/profile/${post.authorUsername}`} className="cc98-last-author">
141	                    {post.authorUsername + '\u200B'}
142	                  </Link>
143	                </div>
144	                <div className="cc98-last-time">
145	                  {formatTime(post.updatedAt || post.createdAt)}
146	                </div>
147	              </td>
148	            </tr>
149	          );
150	        })}
151	      </tbody>
152	
153	      <style>{`
154	        .cc98-topic-list {
155	          width: 100%;
156	          border-collapse: collapse;
157	          border: 1px solid var(--border-color);
158	          border-radius: var(--cc98-radius);
159	          overflow: hidden;
160	          margin-bottom: 1.5rem;
161	          background-color: var(--card-bg);
162	          box-shadow: var(--cc98-shadow);
163	        }
164	        
165	        .cc98-tl-header {
166	          background-color: var(--primary-color);
167	          color: white;
168	        }
169	        
170	        .cc98-tl-header th {
171	          padding: 0.8rem;
172	          text-align: left;
173	          font-size: 0.88rem;
174	          font-weight: bold;
175	          border-bottom: 2px solid var(--accent-color);
176	        }
177	        
178	        .theme-dark .cc98-tl-header th {
179	          border-bottom-color: var(--border-color);
180	        }
181	
182	        .cc98-tl-row {
183	          border-bottom: 1px solid var(--border-color);
184	          transition: var(--cc98-transition);
185	        }
186	        
187	        .cc98-tl-row:last-child {
188	          border-bottom: none;
189	        }
190	
191	        .cc98-tl-row:hover {
192	          background-color: var(--quote-bg);
193	        }
194	        
195	        .sticky-row {
196	          background-color: rgba(218, 180, 77, 0.05);
197	        }
198	
199	        .cc98-tl-cell {
200	          padding: 0.75rem 0.8rem;
201	          font-size: 0.92rem;
202	          vertical-align: middle;
203	        }
204	
205	        .cc98-tl-status {
206	          text-align: center;
207	          color: var(--text-muted);
208	        }
209	
210	        .cc98-tl-status i {
211	          font-size: 1.1rem;
212	        }
213	
214	        .cc98-tl-status i.sticky {
215	          color: #fb6165;
216	        }
217	
218	        .cc98-tl-status i.hot {
219	          color: var(--accent-color);
220	        }
221	
