1	import { useState } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { useQuery } from '@tanstack/react-query';
4	import { getCategories } from '../api/category';
5	import { getPostList } from '../api/post';
6	import { getAnnouncements } from '../api/announcement';
7	import { queryKeys } from '../lib/queryKeys';
8	import BoardCard from '../components/BoardCard';
9	import TopicTable from '../components/TopicTable';
10	import AnnouncementPanel from '../components/AnnouncementPanel';
11	
12	/**
13	 * CC98 风格经典社区首页
14	 */
15	export default function HomePage() {
16	  const navigate = useNavigate();
17	
18	  // 获取公告列表
19	  const { data: announcements = [] } = useQuery({
20	    queryKey: queryKeys.announcements.list(),
21	    queryFn: getAnnouncements,
22	  });
23	
24	  // 获取版块列表
25	  const { data: categories = [], isLoading: isCategoriesLoading } = useQuery({
26	    queryKey: queryKeys.categories.list(),
27	    queryFn: getCategories,
28	  });
29	
30	  const [sortBy, setSortBy] = useState('latest');
31	
32	  // 获取最新/已排序帖子
33	  const { data: recentPostsData, isLoading: isPostsLoading } = useQuery({
34	    queryKey: [...queryKeys.posts.list({ page: 0, size: 10 }), sortBy],
35	    queryFn: () => getPostList(0, 10, undefined, sortBy),
36	  });
37	
38	  // 获取更多帖子用于热门排序
39	  const { data: morePostsData } = useQuery({
40	    queryKey: [...queryKeys.posts.list({ page: 0, size: 50 }), sortBy],
41	    queryFn: () => getPostList(0, 50, undefined, sortBy),
42	  });
43	
44	  // 计算热门帖子（按浏览量排序，取前6个）
45	  const hotPosts = morePostsData?.content
46	    ? [...morePostsData.content].sort((a, b) => b.viewCount - a.viewCount).slice(0, 6)
47	    : [];
48	
49	  const recentPosts = recentPostsData?.content || [];
50	
51	  const isLoading = isCategoriesLoading || isPostsLoading;
52	
53	  if (isLoading) {
54	    return (
55	      <div className="cc98-home-page container">
56	        <div style={{ textAlign: 'center', padding: '5rem 0' }}>
57	          <div className="spinner"></div>
58	          <p style={{ marginTop: '1.25rem', color: 'var(--text-muted)' }}>正在载入 CC91 社区，请稍候...</p>
59	        </div>
60	      </div>
61	    );
62	  }
63	
64	  return (
65	    <div className="cc98-home-page container">
66	
67	      {/* 1. 全站公告 */}
68	      <AnnouncementPanel announcements={announcements} />
69	
70	      {/* 2. 双栏布局 (左栏版块 & 帖子列表，右栏热门) */}
71	      <div className="cc98-home-grid">
72	        <div className="cc98-home-main-col">
73	          {/* 版块区域 */}
74	          <section style={{ marginBottom: '2.5rem' }}>
75	            <div className="cc98-section-title-external">
76	              <i className="fa fa-th-large" style={{ color: 'var(--cc98-alt-color-a)' }}></i> 讨论版块
77	            </div>
78	            <div className="cc98-board-grid">
79	              {categories.map((category) => (
80	                <BoardCard
81	                  key={category.id}
82	                  category={category}
83	                  onClick={(id) => navigate(`/category/${id}`)}
84	                />
85	              ))}
86	            </div>
87	          </section>
88	
89	          {/* 最新主题帖区域 */}
90	          <section>
91	            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', borderBottom: '1px solid var(--border-color)', paddingBottom: '0.5rem' }}>
92	              <div className="cc98-section-title-external" style={{ margin: 0, padding: 0 }}>
93	                <i className="fa fa-clock-o" style={{ color: 'var(--cc98-alt-color-a)' }}></i> 最新帖子
94	              </div>
95	              <div className="cc98-sort-btn-group" style={{ display: 'flex', gap: '0.25rem' }}>
96	                <button
97	                  onClick={() => setSortBy('latest')}
98	                  style={{
99	                    background: sortBy === 'latest' ? 'var(--primary-color)' : 'transparent',
100	                    color: sortBy === 'latest' ? 'white' : 'var(--text-muted)',
101	                    border: '1px solid ' + (sortBy === 'latest' ? 'var(--primary-color)' : 'var(--border-color)'),
102	                    borderRadius: 'var(--cc98-radius-pill)',
103	                    padding: '0.2rem 0.75rem',
104	                    fontSize: '0.75rem',
105	                    fontWeight: 'bold',
106	                    cursor: 'pointer',
107	                    transition: 'var(--cc98-transition)'
108	                  }}
109	                >
110	                  最新发布
111	                </button>
112	                <button
113	                  onClick={() => setSortBy('comments')}
114	                  style={{
115	                    background: sortBy === 'comments' ? 'var(--primary-color)' : 'transparent',
116	                    color: sortBy === 'comments' ? 'white' : 'var(--text-muted)',
117	                    border: '1px solid ' + (sortBy === 'comments' ? 'var(--primary-color)' : 'var(--border-color)'),
118	                    borderRadius: 'var(--cc98-radius-pill)',
119	                    padding: '0.2rem 0.75rem',
120	                    fontSize: '0.75rem',
121	                    fontWeight: 'bold',
122	                    cursor: 'pointer',
123	                    transition: 'var(--cc98-transition)'
124	                  }}
125	                >
