134	                    borderRadius: 'var(--cc98-radius-pill)',
135	                    padding: '0.2rem 0.75rem',
136	                    fontSize: '0.75rem',
137	                    fontWeight: 'bold',
138	                    cursor: 'pointer',
139	                    transition: 'var(--cc98-transition)'
140	                  }}
141	                >
142	                  热门
143	                </button>
144	              </div>
145	            </div>
146	            <TopicTable posts={recentPosts} />
147	          </section>
148	        </div>
149	
150	        {/* 右边栏：今日热门推荐 */}
151	        <div className="cc98-home-sidebar-col">
152	          <div className="cc98-sidebar-wrapper">
153	            <div className="cc98-sidebar-title-external">
154	              <i className="fa fa-fire" style={{ color: '#fb6165' }}></i> 热门帖子
155	            </div>
156	            <div className="cc98-sidebar-box-classic">
