import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { getCategories } from '../api/category';
import { getPostList } from '../api/post';
import { getAnnouncements } from '../api/announcement';
import { queryKeys } from '../lib/queryKeys';
import BoardCard from '../components/BoardCard';
import TopicTable from '../components/TopicTable';
import AnnouncementPanel from '../components/AnnouncementPanel';

/**
 * CC98 风格经典社区首页
 */
export default function HomePage() {
  const navigate = useNavigate();

  // 获取公告列表
  const { data: announcements = [] } = useQuery({
    queryKey: queryKeys.announcements.list(),
    queryFn: getAnnouncements,
  });

  // 获取版块列表
  const { data: categories = [], isLoading: isCategoriesLoading } = useQuery({
    queryKey: queryKeys.categories.list(),
    queryFn: getCategories,
  });

  const [sortBy, setSortBy] = useState('latest');

  // 获取最新/已排序帖子
  const { data: recentPostsData, isLoading: isPostsLoading } = useQuery({
    queryKey: [...queryKeys.posts.list({ page: 0, size: 10 }), sortBy],
    queryFn: () => getPostList(0, 10, undefined, sortBy),
  });

  // 获取更多帖子用于热门排序
  const { data: morePostsData } = useQuery({
    queryKey: [...queryKeys.posts.list({ page: 0, size: 50 }), sortBy],
    queryFn: () => getPostList(0, 50, undefined, sortBy),
  });

  // 计算热门帖子（按浏览量排序，取前6个）
  const hotPosts = morePostsData?.content
    ? [...morePostsData.content].sort((a, b) => b.viewCount - a.viewCount).slice(0, 6)
    : [];

  const recentPosts = recentPostsData?.content || [];

  const isLoading = isCategoriesLoading || isPostsLoading;

  if (isLoading) {
    return (
      <div className="cc98-home-page container">
        <div style={{ textAlign: 'center', padding: '5rem 0' }}>
          <div className="spinner"></div>
          <p style={{ marginTop: '1.25rem', color: 'var(--text-muted)' }}>正在载入 CC91 社区，请稍候...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="cc98-home-page container">

      {/* 1. 全站公告 */}
      <AnnouncementPanel announcements={announcements} />

      {/* 2. 双栏布局 (左栏版块 & 帖子列表，右栏热门) */}
      <div className="cc98-home-grid">
        <div className="cc98-home-main-col">
          {/* 版块区域 */}
          <section style={{ marginBottom: '2.5rem' }}>
            <div className="cc98-section-title-external">
              <i className="fa fa-th-large" style={{ color: 'var(--cc98-alt-color-a)' }}></i> 讨论版块
            </div>
            <div className="cc98-board-grid">
              {categories.map((category) => (
                <BoardCard
                  key={category.id}
                  category={category}
                  onClick={(id) => navigate(`/category/${id}`)}
                />
              ))}
            </div>
          </section>

          {/* 最新主题帖区域 */}
          <section>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', borderBottom: '1px solid var(--border-color)', paddingBottom: '0.5rem' }}>
              <div className="cc98-section-title-external" style={{ margin: 0, padding: 0 }}>
                <i className="fa fa-clock-o" style={{ color: 'var(--cc98-alt-color-a)' }}></i> 最新帖子
              </div>
              <div className="cc98-sort-btn-group" style={{ display: 'flex', gap: '0.25rem' }}>
                <button
                  onClick={() => setSortBy('latest')}
                  style={{
                    background: sortBy === 'latest' ? 'var(--primary-color)' : 'transparent',
                    color: sortBy === 'latest' ? 'white' : 'var(--text-muted)',
                    border: '1px solid ' + (sortBy === 'latest' ? 'var(--primary-color)' : 'var(--border-color)'),
                    borderRadius: 'var(--cc98-radius-pill)',
                    padding: '0.2rem 0.75rem',
                    fontSize: '0.75rem',
                    fontWeight: 'bold',
                    cursor: 'pointer',
                    transition: 'var(--cc98-transition)'
                  }}
                >
                  最新发布
                </button>
                <button
                  onClick={() => setSortBy('comments')}
                  style={{
                    background: sortBy === 'comments' ? 'var(--primary-color)' : 'transparent',
                    color: sortBy === 'comments' ? 'white' : 'var(--text-muted)',
                    border: '1px solid ' + (sortBy === 'comments' ? 'var(--primary-color)' : 'var(--border-color)'),
                    borderRadius: 'var(--cc98-radius-pill)',
                    padding: '0.2rem 0.75rem',
                    fontSize: '0.75rem',
                    fontWeight: 'bold',
                    cursor: 'pointer',
                    transition: 'var(--cc98-transition)'
                  }}
                >
                  最多回复
                </button>
                <button
                  onClick={() => setSortBy('hot')}
                  style={{
                    background: sortBy === 'hot' ? 'var(--primary-color)' : 'transparent',
                    color: sortBy === 'hot' ? 'white' : 'var(--text-muted)',
                    border: '1px solid ' + (sortBy === 'hot' ? 'var(--primary-color)' : 'var(--border-color)'),
                    borderRadius: 'var(--cc98-radius-pill)',
                    padding: '0.2rem 0.75rem',
                    fontSize: '0.75rem',
                    fontWeight: 'bold',
                    cursor: 'pointer',
                    transition: 'var(--cc98-transition)'
                  }}
                >
                  热门
                </button>
              </div>
            </div>
            <TopicTable posts={recentPosts} />
          </section>
        </div>

        {/* 右边栏：今日热门推荐 */}
        <div className="cc98-home-sidebar-col">
          <div className="cc98-sidebar-wrapper">
            <div className="cc98-sidebar-title-external">
              <i className="fa fa-fire" style={{ color: '#fb6165' }}></i> 热门帖子
            </div>
            <div className="cc98-sidebar-box-classic">
              <div className="cc98-sidebar-hot-list">
                {hotPosts.length === 0 ? (
                  <div className="cc98-sidebar-empty">暂无热门主题</div>
                ) : (
                  hotPosts.map((post, index) => (
                    <div key={post.id} className="cc98-sidebar-hot-item">
                      <span className={`cc98-hot-rank ${index < 3 ? 'rank-top' : 'rank-normal'}`}>
                        {index + 1}
                      </span>
                      <div className="cc98-hot-detail">
                        <a
                          href={`/posts/${post.id}`}
                          onClick={(e) => { e.preventDefault(); navigate(`/posts/${post.id}`); }}
                          className="cc98-hot-link"
                          title={post.title}
                        >
                          {post.title}
                        </a>
                        <div className="cc98-hot-meta">
                          <span>阅: {post.viewCount}</span>
                          <span>·</span>
                          <span>评: {post.commentCount}</span>
                          <span>·</span>
                          <span className="cc98-hot-author">{post.authorUsername}</span>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      <style>{`
        .cc98-home-page {
          margin-top: 1.5rem;
        }

        .cc98-home-grid {
          display: grid;
          grid-template-columns: repeat(3, 1fr);
          gap: 1.25rem;
          align-items: flex-start;
        }

        .cc98-home-main-col {
          grid-column: span 2;
          min-width: 0;
        }

        .cc98-home-sidebar-col {
          grid-column: span 1;
          min-width: 0;
        }

        @media (max-width: 992px) {
          .cc98-home-grid {
            grid-template-columns: 1fr;
          }
          .cc98-home-main-col {
            grid-column: span 1;
          }
          .cc98-home-sidebar-col {
            grid-column: span 1;
          }
        }

        .cc98-section-title-external {
          font-size: 1.25rem;
          font-weight: bold;
          color: var(--text-main);
          display: flex;
          align-items: center;
          gap: 0.5rem;
          margin-bottom: 1rem;
          padding-left: 0.25rem;
        }

        .cc98-board-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 1.25rem;
        }

        @media (max-width: 640px) {
          .cc98-board-grid {
            grid-template-columns: 1fr;
            gap: 0.75rem;
          }

          .cc98-section-title-external {
            font-size: 1rem;
          }

          .cc98-sort-btn-group {
            flex-wrap: wrap;
          }

          .cc98-sort-btn-group button {
            font-size: 0.7rem;
            padding: 0.15rem 0.5rem;
          }
        }

        /* Sidebar Styling */
        .cc98-sidebar-wrapper {
          display: flex;
          flex-direction: column;
          width: 100%;
        }

        .cc98-sidebar-title-external {
          font-size: 1.25rem;
          font-weight: bold;
          color: #fb6165;
          display: flex;
          align-items: center;
          gap: 0.5rem;
          margin-bottom: 1rem;
          padding-left: 0.25rem;
        }

        .cc98-sidebar-box-classic {
          border: 1px solid var(--border-color);
          border-radius: var(--cc98-radius);
          background-color: var(--card-bg);
          box-shadow: var(--cc98-shadow);
          overflow: hidden;
        }

        .cc98-sidebar-hot-list {
          padding: 0.75rem 0;
          display: flex;
          flex-direction: column;
        }

        .cc98-sidebar-hot-item {
          display: flex;
          padding: 0.65rem 1rem;
          border-bottom: 1px dashed var(--border-color);
          gap: 0.75rem;
          align-items: flex-start;
        }

        .cc98-sidebar-hot-item:last-child {
          border-bottom: none;
        }

        .cc98-sidebar-hot-item:hover {
          background-color: var(--quote-bg);
        }

        .cc98-hot-rank {
          font-size: 0.75rem;
          font-weight: bold;
          width: 1.25rem;
          height: 1.25rem;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          flex-shrink: 0;
          margin-top: 0.15rem;
        }

        .rank-top {
          background-color: #fb6165;
          color: white;
        }

        .rank-normal {
          background-color: var(--quote-bg);
          color: var(--text-muted);
          border: 1px solid var(--border-color);
        }

        .cc98-hot-detail {
          flex: 1;
          min-width: 0;
        }

        .cc98-hot-link {
          color: var(--text-main);
          font-weight: 500;
          text-decoration: none;
          font-size: 0.88rem;
          display: block;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
          margin-bottom: 0.25rem;
          transition: var(--cc98-transition);
        }

        .cc98-hot-link:hover {
          color: var(--link-color);
          text-decoration: underline;
        }

        .cc98-hot-meta {
          font-size: 0.72rem;
          color: var(--text-muted);
          display: flex;
          gap: 0.35rem;
          align-items: center;
          white-space: nowrap;
        }

        .cc98-hot-author {
          font-weight: bold;
          color: var(--text-main);
          overflow: hidden;
          text-overflow: ellipsis;
          max-width: 80px;
        }

        .cc98-sidebar-empty {
          padding: 3rem 1rem;
          text-align: center;
          color: var(--text-muted);
          font-size: 0.85rem;
        }
      `}</style>
    </div>
  );
}

package com.cc91.forumservice.repository;

import com.cc91.forumservice.entity.Post;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 帖子数据访问层
 */
@Repository
public interface PostRepository extends JpaRepository<Post, Long> {

    /**
     * 按作者ID查询帖子列表
     */
    List<Post> findByAuthorId(Long authorId);

    /**
     * 按作者ID查询帖子列表（按时间倒序）
     */
    List<Post> findByAuthorIdOrderByCreatedAtDesc(Long authorId);

    /**
     * 按作者ID和状态查询帖子列表（按时间倒序）
     */
    List<Post> findByAuthorIdAndStatusOrderByCreatedAtDesc(Long authorId, String status);

    /**
     * 按作者ID分页查询帖子
     */
    Page<Post> findByAuthorId(Long authorId, Pageable pageable);

    /**
     * 按状态分页查询帖子
     */
    Page<Post> findByStatus(String status, Pageable pageable);

    /**
     * 按版块ID和状态分页查询帖子
     */
    Page<Post> findByCategoryIdAndStatus(Long categoryId, String status, Pageable pageable);

    /**
     * 统计某分类下的帖子数量（所有状态，用于删除前检查）
     */
    long countByCategoryId(Long categoryId);

    /**
     * 统计某分类下的已发布帖子数量
     */
    long countByCategoryIdAndStatus(Long categoryId, String status);

    long countByCategoryIdAndStatusAndCreatedAtAfter(Long categoryId, String status, LocalDateTime since);

    /**
     * 批量统计各版块的已发布帖子数和今日新帖数（单次查询）
     */
    @Query("SELECT p.categoryId, COUNT(p), " +
           "SUM(CASE WHEN p.createdAt >= :todayStart THEN 1 ELSE 0 END) " +
           "FROM Post p WHERE p.status = :status GROUP BY p.categoryId")
    List<Object[]> countStatsByCategory(@Param("status") String status, @Param("todayStart") LocalDateTime todayStart);

    /**
     * 按标题或内容搜索帖子（分页）
     * 只返回指定状态的帖子
     */
    Page<Post> findByStatusAndTitleContainingOrStatusAndContentContaining(
            String status, String titleKeyword,
            String status2, String contentKeyword,
            Pageable pageable
    );

    /**
     * 原子更新浏览量（避免并发竞态条件）
     */
    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Query("UPDATE Post p SET p.viewCount = p.viewCount + 1 WHERE p.id = :id")
    void incrementViewCount(@Param("id") Long id);
}

