42	  });
43	
44	  // 举报页加载评论列表，用于建立 commentId -> postId 映射
45	  const { data: reportComments = [] } = useQuery({
46	    queryKey: ['admin', 'comments'],
47	    queryFn: adminGetComments,
48	    enabled: activeTab === 'reports',
49	  });
50	
51	  const commentPostMap = useMemo(() => {
52	    const map = new Map<number, number>();
53	    reportComments.forEach(c => map.set(c.id, c.postId));
54	    return map;
55	  }, [reportComments]);
56	
57	  // 更新帖子状态
58	  const statusMutation = useMutation({
59	    mutationFn: ({ postId, status }: { postId: number; status: string }) =>
60	      adminUpdatePostStatus(postId, status),
61	    onSuccess: () => {
62	      queryClient.invalidateQueries({ queryKey: queryKeys.admin.posts() });
63	      setSuccess('状态更新成功');
64	    },
65	    onError: (err: any) => {
66	      setError(err.response?.data?.message || '更新失败');
67	    },
68	  });
69	
70	  // 删除帖子
71	  const deletePostMutation = useMutation({
72	    mutationFn: adminDeletePost,
73	    onSuccess: () => {
74	      queryClient.invalidateQueries({ queryKey: queryKeys.admin.posts() });
75	      setSuccess('帖子删除成功');
76	    },
77	    onError: (err: any) => {
78	      setError(err.response?.data?.message || '删除失败');
79	    },
80	  });
81	
82	  // 删除评论
83	  const deleteCommentMutation = useMutation({
84	    mutationFn: adminDeleteComment,
85	    onSuccess: () => {
86	      queryClient.invalidateQueries({ queryKey: ['admin', 'comments'] });
87	      setSuccess('评论删除成功');
88	    },
89	    onError: (err: any) => {
90	      setError(err.response?.data?.message || '删除失败');
91	    },
92	  });
93	
94	  // 处理举报
95	  const handleReportMutation = useMutation({
96	    mutationFn: ({ id, status }: { id: number; status: 'RESOLVED' | 'DISMISSED' }) =>
97	      adminHandleReport(id, status),
98	    onSuccess: () => {
99	      queryClient.invalidateQueries({ queryKey: ['admin', 'reports'] });
100	      setSuccess('举报处理成功');
101	    },
102	    onError: (err: any) => {
103	      setError(err.response?.data?.message || '处理失败');
104	    },
105	  });
106	
107	  const handleResolveReport = async (report: any) => {
108	    if (!confirm(`确定要处理此举报并删除该内容吗？此操作不可恢复。`)) return;
109	
110	    try {
111	      if (report.targetType === 'POST') {
112	        await deletePostMutation.mutateAsync(report.targetId);
113	      } else {
114	        await deleteCommentMutation.mutateAsync(report.targetId);
115	      }
116	      await handleReportMutation.mutateAsync({ id: report.id, status: 'RESOLVED' });
117	    } catch (err: any) {
