32	public class AdminContentController {
33	
34	    private static final Logger logger = LoggerFactory.getLogger(AdminContentController.class);
35	
36	    private final PostRepository postRepository;
37	    private final CommentRepository commentRepository;
38	    private final PostService postService;
39	    private final NotificationServiceClient notificationServiceClient;
40	    private final UserServiceClient userServiceClient;
41	
42	    public AdminContentController(PostRepository postRepository,
43	                                  CommentRepository commentRepository,
44	                                  PostService postService,
45	                                  NotificationServiceClient notificationServiceClient,
46	                                  UserServiceClient userServiceClient) {
47	        this.postRepository = postRepository;
48	        this.commentRepository = commentRepository;
49	        this.postService = postService;
50	        this.notificationServiceClient = notificationServiceClient;
51	        this.userServiceClient = userServiceClient;
52	    }
53	
54	    @GetMapping("/posts")
55	    public ResponseEntity<List<PostResponse>> getPostsByStatus(
56	            @RequestParam(required = false) String status
57	    ) {
58	        List<PostResponse> response = postService.getPostList(0, 1000, status).getContent();
59	        return ResponseEntity.ok(response);
60	    }
61	
62	    @GetMapping("/comments")
63	    public ResponseEntity<List<Map<String, Object>>> getComments() {
64	        List<Comment> comments = commentRepository.findAllWithPostByOrderByCreatedAtDesc();
65	
66	        Set<Long> authorIds = comments.stream()
67	                .map(Comment::getAuthorId)
68	                .collect(Collectors.toSet());
69	
70	        Map<Long, UserInfoDTO> userMap;
71	        try {
72	            List<UserInfoDTO> users = userServiceClient.getUsersByIds(List.copyOf(authorIds));
73	            userMap = users.stream().collect(Collectors.toMap(UserInfoDTO::getId, u -> u));
74	        } catch (Exception e) {
75	            logger.warn("批量查询用户信息失败: {}", e.getMessage());
76	            userMap = Map.of();
77	        }
78	        final Map<Long, UserInfoDTO> finalUserMap = userMap;
79	
80	        List<Map<String, Object>> result = comments.stream().map(c -> {
81	            UserInfoDTO author = finalUserMap.get(c.getAuthorId());
82	            String postTitle = c.getPost() != null ? c.getPost().getTitle() : "未知帖子";
83	            return Map.<String, Object>of(
84	                    "id", c.getId(),
85	                    "postId", c.getPostId(),
86	                    "postTitle", postTitle,
87	                    "authorId", c.getAuthorId(),
88	                    "authorUsername", author != null ? author.getUsername() : "未知用户",
89	                    "content", c.getContent(),
90	                    "parentId", c.getParentId() != null ? c.getParentId() : 0L,
91	                    "status", c.getStatus(),
92	                    "createdAt", c.getCreatedAt().toString()
93	            );
94	        }).collect(Collectors.toList());
95	
96	        return ResponseEntity.ok(result);
97	    }
98	
99	    @PutMapping("/posts/{id}/status")
100	    @Transactional
101	    public ResponseEntity<ApiResponse<Void>> updatePostStatus(
102	            @PathVariable Long id,
103	            @Valid @RequestBody UpdatePostStatusRequest request
104	    ) {
105	        Post post = postRepository.findById(id)
106	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
107	
108	        post.setStatus(request.getStatus());
109	        postRepository.save(post);
110	
111	        try {
112	            notificationServiceClient.createNotification(new CreateNotificationRequest(
113	                    post.getAuthorId(), "POST_STATUS", "帖子状态变更",
114	                    "您的帖子「" + post.getTitle() + "」状态已变更为：" + request.getStatus(),
115	                    post.getId()
116	            ));
117	        } catch (Exception e) {
118	            logger.warn("通知发送失败: postId={}", id, e);
119	        }
120	
121	        logger.info("管理员修改帖子状态: id={}, status={}", id, request.getStatus());
122	        return ResponseEntity.ok(ApiResponse.success("帖子状态已更新"));
123	    }
124	
125	    @DeleteMapping("/posts/{id}")
126	    public ResponseEntity<ApiResponse<Void>> forceDeletePost(@PathVariable Long id) {
127	        Post post = postRepository.findById(id)
128	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
129	        postRepository.delete(post);
130	        logger.info("管理员强制删除帖子: id={}", id);
131	        return ResponseEntity.ok(ApiResponse.success("帖子已删除"));
132	    }
133	
134	    @DeleteMapping("/comments/{id}")
135	    public ResponseEntity<ApiResponse<Void>> forceDeleteComment(@PathVariable Long id) {
136	        Comment comment = commentRepository.findById(id)
137	                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));
138	        commentRepository.delete(comment);
139	        logger.info("管理员强制删除评论: id={}", id);
140	        return ResponseEntity.ok(ApiResponse.success("评论已删除"));
141	    }
142	}
